-- Generated from data/menu.js. Review changes against the nine owner-supplied images.
-- Repeatable: updates official catalog metadata and prices, never opens ordering.
on conflict(catalog_key) do update set product_key=excluded.product_key,name=excluded.name,category=excluded.category,category_key=excluded.category_key,variant_label=excluded.variant_label,price=excluded.price,source_page=excluded.source_page,sort_order=excluded.sort_order,review_note=excluded.review_note,published=excluded.published;

-- The supplied store location is confirmed. Delivery fee and radius remain unapproved.
update public.shop_settings set name='Adriano’s',address='Burgos Street, Brgy. 3 Poblacion, La Carlota City (In front of McDonald’s Drive Thru)',latitude=10.423282164368267,longitude=122.91901469110203,accepting_orders=false where id;
